int main(void){const mpc_engine_t*e=mpc_engine();void*a=e->create(NULL),*b=e->create(NULL);assert(a&&b);int16_t out[256];char state[16384],x[16384];for(int model=0;model<16;model++){char v[16];snprintf(v,sizeof(v),"%d",model);e->set_param(a,"all_notes_off","1");e->set_param(a,"osc_type",v);uint8_t on[]={0x90,60,100};e->midi(a,on,3);long energy=0;for(int j=0;j<100;j++){e->render(a,out,128);for(int i=0;i<256;i++)energy+=abs(out[i]);}assert(energy>10000);}e->set_param(a,"matrix_2_3","-50");assert(e->get_param(a,"state",state,sizeof(state))>0);e->set_param(b,"state",state);assert(e->get_param(b,"state",x,sizeof(x))>0);assert(!strcmp(state,x));e->set_param(b,"state","MFZ1;nan;");e->get_param(b,"state",x,sizeof(x));assert(!strcmp(state,x));e->set_param(a,"all_notes_off","1");for(int j=0;j<100;j++)e->render(a,out,127);for(int i=0;i<254;i++)assert(out[i]==0);for(int i=0;i<128;i++)e->render(b,out,1);char dir[128],path[160];snprintf(dir,sizeof(dir),"/tmp/microfreeze-test-%ld",(long)getpid());assert(mkdir(dir,0700)==0);snprintf(path,sizeof(path),"%s/01-good.mfz",dir);FILE*file=fopen(path,"w");assert(file);fprintf(file,"MFZNAME:Imported Test\n%s\n",state);fclose(file);void*c=e->create(dir);assert(c);e->get_param(c,"bank_count",x,sizeof(x));assert(atoi(x)==9);e->get_param(c,"preset:8",x,sizeof(x));assert(!strcmp(x,"Imported Test"));e->set_param(c,"preset","8");e->get_param(c,"preset",x,sizeof(x));assert(atoi(x)==8);e->set_param(c,"preset","511");e->get_param(c,"preset",x,sizeof(x));assert(atoi(x)==511);e->get_param(c,"preset:511",x,sizeof(x));assert(!strcmp(x,"Unavailable slot 511"));for(int direction=0;direction<2;direction++){float previous=direction?511:0;for(int step=0;step<=2044;step++){float requested=(direction?2044-step:step)*.25f;char value[32];snprintf(value,sizeof(value),"%.2f",requested);e->set_param(c,"preset",value);e->get_param(c,"preset",x,sizeof(x));float selected=strtof(x,NULL);assert(selected==roundf(requested));assert(direction?selected<=previous:selected>=previous);previous=selected;}}e->set_param(c,"preset","511");e->get_param(c,"state",x,sizeof(x));e->set_param(b,"state",x);e->get_param(b,"preset",x,sizeof(x));assert(atoi(x)==511);e->destroy(c);assert(unlink(path)==0);assert(rmdir(dir)==0);e->destroy(a);e->destroy(b);puts("engine: 16 model audio, state roundtrip, malformed state, panic, variable blocks, external bank, preset sweep/save PASS");}
